import { useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { Home, ArrowRight, Sparkles } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type Props = { app?: AppHandle };

const PHOTO = "https://images.unsplash.com/photo-1499793983690-e29da59ef1c2?auto=format&fit=crop&w=1200&q=70";

const DEMOS = [
  { label: "Maya · Guest", email: "maya@nook.test" },
  { label: "Lucas · Guest", email: "lucas@nook.test" },
  { label: "Amelia · Host", email: "amelia@nook.test" },
  { label: "Rafael · Host", email: "rafael@nook.test" },
];

const HAND = { fontFamily: "'Caveat','Bradley Hand','Segoe Print','Comic Sans MS',cursive" } as const;
const LINEN = {
  backgroundColor: "#efe7da",
  backgroundImage:
    "repeating-linear-gradient(0deg, rgba(120,95,60,0.07) 0 1px, transparent 1px 3px), repeating-linear-gradient(90deg, rgba(120,95,60,0.07) 0 1px, transparent 1px 3px), radial-gradient(ellipse at 50% 30%, rgba(255,255,255,0.55), transparent 70%)",
} as const;

const INPUT =
  "w-full border-0 border-b-2 border-dashed border-neutral-400/70 bg-transparent px-1 py-2.5 text-base text-neutral-900 outline-none transition placeholder:text-neutral-400 focus:border-primary";

function GoogleG() {
  return (
    <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden="true">
      <path fill="#EA4335" d="M24 9.5c3.5 0 6.6 1.2 9.1 3.6l6.8-6.8C35.8 2.4 30.3 0 24 0 14.6 0 6.5 5.4 2.6 13.2l7.9 6.1C12.4 13.6 17.7 9.5 24 9.5z" />
      <path fill="#4285F4" d="M46.5 24.5c0-1.6-.1-3.1-.4-4.5H24v9h12.7c-.6 3-2.3 5.5-4.8 7.2l7.5 5.8c4.4-4.1 7.1-10.1 7.1-17.5z" />
      <path fill="#FBBC05" d="M10.5 28.7A14.5 14.5 0 0 1 9.5 24c0-1.6.3-3.2.8-4.7l-7.9-6.1A24 24 0 0 0 0 24c0 3.9.9 7.5 2.6 10.8l7.9-6.1z" />
      <path fill="#34A853" d="M24 48c6.5 0 11.9-2.1 15.9-5.8l-7.5-5.8c-2.1 1.4-4.8 2.3-8.4 2.3-6.3 0-11.6-4.1-13.5-9.8l-7.9 6.1C6.5 42.6 14.6 48 24 48z" />
    </svg>
  );
}

export default function NookLogin({ app }: Props) {
  const reduce = useReducedMotion();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const signup = app?.auth?.mode === "signup";
  const providers = app?.auth?.providers ?? [];

  const submit = async () => {
    if (!app) return;
    setBusy(true);
    setError("");
    try {
      if (signup) await app.auth.signUp({ name: name || email.split("@")[0], email, password });
      else await app.auth.signIn(email, password);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Something went wrong");
    }
    setBusy(false);
  };

  const provider = async (p: string) => {
    if (!app) return;
    setError("");
    try {
      await app.auth.startProvider(p);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Couldn't start that sign-in");
    }
  };

  return (
    <div className="relative flex min-h-screen w-full items-center justify-center overflow-hidden px-4 py-10 sm:px-8" style={LINEN}>
      <div className="relative w-full max-w-4xl">
        <motion.div
          aria-hidden="true"
          initial={reduce ? false : { opacity: 0, rotate: 0, y: 40 }}
          animate={{ opacity: 1, rotate: 5, y: 0 }}
          transition={{ type: "spring", stiffness: 70, damping: 16, delay: 0.1 }}
          className="absolute inset-0 translate-x-3 translate-y-5 overflow-hidden rounded-xl bg-white p-2 shadow-[0_18px_40px_rgba(70,50,20,0.28)] sm:translate-x-10 sm:translate-y-6"
        >
          <img src={PHOTO} alt="" className="h-full w-full rounded-lg object-cover" />
          <span className="absolute bottom-4 right-6 text-2xl text-white drop-shadow" style={HAND}>
            Greetings from the nook!
          </span>
        </motion.div>

        <motion.div
          initial={reduce ? false : { opacity: 0, rotate: -6, y: -60 }}
          animate={{ opacity: 1, rotate: -1.5, y: 0 }}
          transition={{ type: "spring", stiffness: 90, damping: 14 }}
          className="relative grid rounded-xl bg-[#fffdf8] p-5 shadow-[0_24px_60px_rgba(70,50,20,0.3)] sm:p-8 md:grid-cols-[1fr_1.1fr] md:gap-0"
        >
          <div className="absolute right-4 top-4 z-10 flex items-start gap-2 sm:right-6 sm:top-6">
            <motion.div
              initial={reduce ? false : { opacity: 0, scale: 1.6, rotate: -20 }}
              animate={{ opacity: 0.8, scale: 1, rotate: -12 }}
              transition={{ delay: 0.7, type: "spring", stiffness: 200, damping: 14 }}
              className="mt-3 flex h-16 w-16 flex-col items-center justify-center rounded-full border-2 border-neutral-600/70 text-[9px] font-bold uppercase leading-tight tracking-wider text-neutral-600/80"
            >
              <span>Nook Post</span>
              <span className="text-[11px]">OCT 12</span>
              <span>★ ★ ★</span>
            </motion.div>
            <div
              className="flex h-[74px] w-14 items-center justify-center bg-primary p-1.5 shadow-md"
              style={{ clipPath: "polygon(0 4%,4% 0,10% 4%,16% 0,22% 4%,28% 0,34% 4%,40% 0,46% 4%,52% 0,58% 4%,64% 0,70% 4%,76% 0,82% 4%,88% 0,94% 4%,100% 0,96% 10%,100% 16%,96% 22%,100% 28%,96% 34%,100% 40%,96% 46%,100% 52%,96% 58%,100% 64%,96% 70%,100% 76%,96% 82%,100% 88%,96% 94%,100% 100%,94% 96%,88% 100%,82% 96%,76% 100%,70% 96%,64% 100%,58% 96%,52% 100%,46% 96%,40% 100%,34% 96%,28% 100%,22% 96%,16% 100%,10% 96%,4% 100%,0 96%,4% 90%,0 84%,4% 78%,0 72%,4% 66%,0 60%,4% 54%,0 48%,4% 42%,0 36%,4% 30%,0 24%,4% 18%,0 12%,4% 6%)" }}
            >
              <div className="flex h-full w-full flex-col items-center justify-center border border-white/70 text-white">
                <Home size={20} />
                <span className="mt-1 text-[8px] font-bold uppercase tracking-widest">nook</span>
              </div>
            </div>
          </div>

          <div className="pb-6 pr-0 pt-16 md:border-r md:border-dashed md:border-neutral-300 md:pb-2 md:pr-8 md:pt-2">
            <h1 className="text-5xl leading-[0.95] text-neutral-900 sm:text-6xl" style={HAND}>
              {signup ? "Find your next nook!" : "Dear traveller,"}
            </h1>
            <p className="mt-4 text-2xl leading-snug text-neutral-700" style={HAND}>
              {signup
                ? "Pop your details on the card and we'll hold a window seat for you."
                : "Welcome back! Sign in below to see your trips, requests and saved stays."}
            </p>
            <div className="mt-6 hidden md:block">
              <p className="mb-2 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-neutral-500">
                <Sparkles size={13} /> Try a demo
              </p>
              <div className="flex flex-wrap gap-2">
                {DEMOS.map((d) => (
                  <button
                    key={d.email}
                    onClick={() => {
                      setEmail(d.email);
                      setPassword("coral-sunrise-2026");
                    }}
                    className="rounded-full border border-neutral-300 bg-white px-3 py-1 text-sm font-medium text-neutral-700 shadow-sm transition hover:border-primary hover:text-primary"
                  >
                    {d.label}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="md:pl-8 md:pt-24">
            <div className="space-y-3">
              <AnimatePresence initial={false}>
                {signup && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                    <input aria-label="Name" type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="Your name" className={INPUT} />
                  </motion.div>
                )}
              </AnimatePresence>
              <input id="nook-email" aria-label="Email" type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Email" className={INPUT} />
              <input id="nook-password" aria-label="Password" type="password" autoComplete={signup ? "new-password" : "current-password"} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Password" className={INPUT} />
            </div>

            <AnimatePresence>
              {error && (
                <motion.p initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-600">
                  {error}
                </motion.p>
              )}
            </AnimatePresence>

            <motion.button
              whileTap={reduce ? undefined : { scale: 0.97 }}
              whileHover={reduce ? undefined : { y: -1 }}
              onClick={submit}
              disabled={busy}
              className="mt-5 flex w-full items-center justify-center gap-2 rounded-full bg-primary px-5 py-3.5 font-semibold text-white shadow-[0_10px_24px_rgba(255,90,95,0.4)] disabled:opacity-60"
            >
              {signup ? (busy ? "Creating…" : "Create account") : "Sign in"}
              {!signup && <ArrowRight size={18} />}
            </motion.button>

            {providers.length > 0 && (
              <>
                <div className="my-4 flex items-center gap-3 text-xs uppercase tracking-widest text-neutral-400">
                  <span className="h-px flex-1 bg-neutral-300" />
                  or
                  <span className="h-px flex-1 bg-neutral-300" />
                </div>
                <div className="space-y-2">
                  {providers.map((p) => (
                    <motion.button
                      key={p.name}
                      whileTap={reduce ? undefined : { scale: 0.97 }}
                      onClick={() => provider(p.name)}
                      className="flex w-full items-center justify-center gap-3 rounded-full border border-neutral-300 bg-white px-5 py-3 text-sm font-semibold text-neutral-800 shadow-sm transition hover:border-neutral-400"
                    >
                      {p.name === "google" && <GoogleG />}
                      Continue with {p.label}
                    </motion.button>
                  ))}
                </div>
              </>
            )}

            <p className="mt-5 text-center text-sm text-neutral-600">
              {signup ? "Already have an account?" : "New to Nook?"}{" "}
              <button onClick={() => app?.auth?.setMode?.(signup ? "login" : "signup")} className="font-semibold text-primary underline-offset-4 hover:underline">
                {signup ? "Log in instead" : "Create an account"}
              </button>
            </p>

            <div className="mt-5 md:hidden">
              <p className="mb-2 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-neutral-500">
                <Sparkles size={13} /> Try a demo
              </p>
              <div className="flex flex-wrap gap-2">
                {DEMOS.map((d) => (
                  <button
                    key={d.email}
                    onClick={() => {
                      setEmail(d.email);
                      setPassword("coral-sunrise-2026");
                    }}
                    className="rounded-full border border-neutral-300 bg-white px-3 py-1 text-sm font-medium text-neutral-700 shadow-sm"
                  >
                    {d.label}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
}

import { useState, useMemo, useRef, useEffect } from "react";
import { motion, AnimatePresence, LayoutGroup, useReducedMotion, useMotionValue, animate } from "motion/react";
import { Heart, Star, MapPin, Users, X, ChevronLeft, ChevronRight, Search, Sparkles, Home, Calendar, LogOut, Check, Coffee, Flame, Sun, Globe, Utensils, ArrowLeft } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type Row = Record<string, unknown>;
type Range = { a: string; b: string };
type Pics = Record<string, string | string[]>;
type Props = { app?: AppHandle; pics?: Pics; peek?: string };

const s = (v: unknown) => (v == null ? "" : String(v));
const n = (v: unknown) => Number(v) || 0;
const money = (v: number) => "$" + Math.round(v).toLocaleString("en-US");
const pad = (x: number) => String(x).padStart(2, "0");
const iso = (y: number, m: number, d: number) => y + "-" + pad(m + 1) + "-" + pad(d);
const todayIso = () => {
  const d = new Date();
  return iso(d.getFullYear(), d.getMonth(), d.getDate());
};
const utc = (d: string) => Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10));
const diffDays = (a: string, b: string) => Math.round((utc(b) - utc(a)) / 86400000);
const fmt = (d: string) => (d ? new Date(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10)).toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "Add date");
const photosOf = (r: Row, pics?: Pics) => {
  const v = pics ? pics[s(r.title)] : undefined;
  return Array.isArray(v) ? v : [r.cover, r.photo_2, r.photo_3, r.photo_4].map(s).filter(Boolean);
};
const cov = (p: Pics | undefined, k: string, d: string) => {
  const v = p ? p[k] : undefined;
  return typeof v === "string" ? v : d;
};
const SHADOW = "shadow-[0_1px_2px_rgba(16,24,40,0.04),0_8px_28px_rgba(16,24,40,0.07)]";
const AMEN: Record<string, typeof Check> = { wifi: Globe, kitchen: Utensils, fireplace: Flame, "hot tub": Flame, breakfast: Coffee, terrace: Sun };

function Carousel({ photos, alt, onTap }: { photos: string[]; alt: string; onTap?: (i: number) => void }) {
  const reduce = useReducedMotion();
  const box = useRef<HTMLDivElement>(null);
  const [w, setW] = useState(0);
  const [i, setI] = useState(0);
  const x = useMotionValue(0);
  const last = Math.max(0, photos.length - 1);
  useEffect(() => {
    const m = () => setW(box.current ? box.current.offsetWidth : 0);
    m();
    window.addEventListener("resize", m);
    return () => window.removeEventListener("resize", m);
  }, []);
  useEffect(() => {
    const c = animate(x, -i * w, reduce ? { duration: 0 } : { type: "spring", stiffness: 320, damping: 36 });
    return () => c.stop();
  }, [i, w, reduce, x]);
  const go = (k: number) => setI(Math.max(0, Math.min(last, k)));
  return (
    <div ref={box} className="relative h-full w-full overflow-hidden bg-neutral-100">
      <motion.div
        drag="x"
        dragConstraints={{ left: -last * w, right: 0 }}
        dragElastic={0.15}
        style={{ x }}
        onDragEnd={(_, info) => {
          if (info.offset.x < -w / 4 || info.velocity.x < -450) go(i + 1);
          else if (info.offset.x > w / 4 || info.velocity.x > 450) go(i - 1);
          else animate(x, -i * w, { type: "spring", stiffness: 320, damping: 36 });
        }}
        onTap={() => onTap && onTap(i)}
        className="flex h-full cursor-grab active:cursor-grabbing"
      >
        {photos.map((p, k) => (
          <img key={k} src={p} alt={alt} draggable={false} className="h-full w-full shrink-0 select-none object-cover" />
        ))}
      </motion.div>
      {photos.length > 1 && (
        <div className="pointer-events-none absolute inset-x-0 bottom-3 flex justify-center gap-1.5">
          {photos.map((_, k) => (
            <motion.span key={k} animate={{ width: k === i ? 16 : 6, opacity: k === i ? 1 : 0.6 }} className="h-1.5 rounded-full bg-white shadow" />
          ))}
        </div>
      )}
    </div>
  );
}

function Gallery({ photos, start, title, onClose }: { photos: string[]; start: number; title: string; onClose: () => void }) {
  const reduce = useReducedMotion();
  const [[i, dir], setS] = useState<[number, number]>([start, 0]);
  const go = (d: number) => setS(([c]) => [Math.max(0, Math.min(photos.length - 1, c + d)), d]);
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      if (e.key === "ArrowRight") go(1);
      if (e.key === "ArrowLeft") go(-1);
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  });
  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[60] flex flex-col bg-black/95">
      <div className="flex items-center justify-between px-4 py-4 text-white">
        <button aria-label="Close gallery" onClick={onClose} className="flex h-10 w-10 items-center justify-center rounded-full bg-white/10"><X size={20} /></button>
        <div className="text-center"><p className="text-sm font-semibold">{title}</p><p className="text-xs text-white/60">{i + 1} / {photos.length}</p></div>
        <span className="w-10" />
      </div>
      <div className="relative flex min-h-0 flex-1 items-center justify-center overflow-hidden px-2 pb-6">
        <AnimatePresence initial={false} custom={dir} mode="popLayout">
          <motion.img
            key={i}
            src={photos[i]}
            alt={title}
            custom={dir}
            variants={{ enter: (d: number) => ({ x: reduce ? 0 : d * 120, opacity: 0, scale: 0.97 }), center: { x: 0, opacity: 1, scale: 1 }, exit: (d: number) => ({ x: reduce ? 0 : d * -120, opacity: 0, scale: 0.97 }) }}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{ type: "spring", stiffness: 280, damping: 32 }}
            drag="x"
            dragConstraints={{ left: 0, right: 0 }}
            dragElastic={0.4}
            onDragEnd={(_, info) => {
              if (info.offset.x < -80) go(1);
              else if (info.offset.x > 80) go(-1);
            }}
            draggable={false}
            className="max-h-full max-w-full select-none rounded-2xl object-contain"
          />
        </AnimatePresence>
        <button aria-label="Previous photo" disabled={i === 0} onClick={() => go(-1)} className="absolute left-4 hidden h-12 w-12 items-center justify-center rounded-full bg-white/15 text-white disabled:opacity-20 lg:flex"><ChevronLeft /></button>
        <button aria-label="Next photo" disabled={i === photos.length - 1} onClick={() => go(1)} className="absolute right-4 hidden h-12 w-12 items-center justify-center rounded-full bg-white/15 text-white disabled:opacity-20 lg:flex"><ChevronRight /></button>
      </div>
    </motion.div>
  );
}

function Cal({ busy, start, end, onPick, today, months }: { busy: Range[]; start: string; end: string; onPick: (d: string) => void; today: string; months: number }) {
  const [off, setOff] = useState(0);
  const isBusy = (d: string) => busy.some((r) => r.a <= d && d < r.b);
  const y0 = +today.slice(0, 4);
  const m0 = +today.slice(5, 7) - 1 + off;
  return (
    <div>
      <div className="mb-3 flex items-center justify-between">
        <button aria-label="Previous month" disabled={off === 0} onClick={() => setOff(off - 1)} className="flex h-9 w-9 items-center justify-center rounded-full border border-neutral-200 disabled:opacity-30"><ChevronLeft size={16} /></button>
        <button aria-label="Next month" onClick={() => setOff(off + 1)} className="flex h-9 w-9 items-center justify-center rounded-full border border-neutral-200"><ChevronRight size={16} /></button>
      </div>
      <AnimatePresence mode="wait" initial={false}>
        <motion.div key={off} initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -16 }} transition={{ duration: 0.18 }} className={"grid gap-8 " + (months > 1 ? "grid-cols-2" : "grid-cols-1")}>
          {Array.from({ length: months }).map((_, mi) => {
            const first = new Date(y0, m0 + mi, 1);
            const yy = first.getFullYear();
            const mm = first.getMonth();
            const days = new Date(yy, mm + 1, 0).getDate();
            return (
              <div key={mi}>
                <p className="mb-3 text-center text-sm font-semibold">{first.toLocaleDateString("en-US", { month: "long", year: "numeric" })}</p>
                <div className="grid grid-cols-7 text-center text-[11px] font-medium text-neutral-400">
                  {["S", "M", "T", "W", "T", "F", "S"].map((d, k) => <span key={k} className="pb-1">{d}</span>)}
                </div>
                <div className="grid grid-cols-7 gap-y-1">
                  {Array.from({ length: first.getDay() }).map((_, k) => <span key={"e" + k} />)}
                  {Array.from({ length: days }).map((_, k) => {
                    const d = iso(yy, mm, k + 1);
                    const past = d < today;
                    const b = isBusy(d);
                    const sel = d === start || d === end;
                    const inR = !!start && !!end && d >= start && d <= end;
                    const disabled = past || (b && !(start && !end && d > start));
                    return (
                      <div key={d} className={"flex h-10 items-center justify-center " + (inR ? "bg-primary/10" : "")}>
                        <motion.button
                          whileTap={{ scale: 0.88 }}
                          disabled={disabled}
                          onClick={() => onPick(d)}
                          aria-label={d}
                          className={"flex h-9 w-9 items-center justify-center rounded-full text-sm transition " + (sel ? "bg-primary font-semibold text-white shadow-md" : past || b ? "text-neutral-300 " + (b && !past ? "line-through" : "") : "text-neutral-800 hover:bg-neutral-100")}
                        >
                          {k + 1}
                        </motion.button>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

function Panel(p: { stay: Row; start: string; end: string; guests: number; setGuests: (g: number) => void; submitting: boolean; done: boolean; hostName: string; onSubmit: () => void; onTrips: () => void; onDates: () => void }) {
  const nights = p.start && p.end ? diffDays(p.start, p.end) : 0;
  const price = n(p.stay.price_per_night);
  const sub = nights * price;
  const total = nights ? sub + n(p.stay.cleaning_fee) : 0;
  const max = n(p.stay.max_guests) || 1;
  if (p.done)
    return (
      <div className="flex flex-col items-center px-4 py-10 text-center">
        <motion.span initial={{ scale: 0 }} animate={{ scale: 1 }} transition={{ type: "spring", stiffness: 260, damping: 14 }} className="mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-primary text-white shadow-[0_12px_30px_rgba(255,90,95,0.45)]"><Check size={30} /></motion.span>
        <h3 className="font-serif text-2xl">Request sent</h3>
        <p className="mt-2 text-sm text-neutral-500">{p.hostName} will confirm {fmt(p.start)} → {fmt(p.end)} soon.</p>
        <button onClick={p.onTrips} className="mt-6 rounded-2xl bg-neutral-900 px-6 py-3 text-sm font-semibold text-white">View my trips</button>
      </div>
    );
  const step = "flex h-8 w-8 items-center justify-center rounded-full border border-neutral-300 text-lg disabled:opacity-30";
  return (
    <div>
      <div className="flex items-baseline gap-1"><span className="text-2xl font-bold">{money(price)}</span><span className="text-neutral-500">night</span></div>
      <div className="mt-4 grid grid-cols-2 overflow-hidden rounded-2xl border border-neutral-200">
        <button onClick={p.onDates} className="border-r border-neutral-200 px-4 py-3 text-left"><span className="block text-[10px] font-bold uppercase tracking-wider text-neutral-500">Check-in</span><span className="text-sm">{fmt(p.start)}</span></button>
        <button onClick={p.onDates} className="px-4 py-3 text-left"><span className="block text-[10px] font-bold uppercase tracking-wider text-neutral-500">Check-out</span><span className="text-sm">{fmt(p.end)}</span></button>
      </div>
      <div className="mt-3 flex items-center justify-between rounded-2xl border border-neutral-200 px-4 py-3">
        <div><span className="block text-[10px] font-bold uppercase tracking-wider text-neutral-500">Guests</span><span className="text-sm">{p.guests} guest{p.guests > 1 ? "s" : ""} <span className="text-neutral-400">· max {max}</span></span></div>
        <div className="flex items-center gap-3">
          <motion.button whileTap={{ scale: 0.85 }} aria-label="Fewer guests" disabled={p.guests <= 1} onClick={() => p.setGuests(p.guests - 1)} className={step}>−</motion.button>
          <motion.button whileTap={{ scale: 0.85 }} aria-label="More guests" disabled={p.guests >= max} onClick={() => p.setGuests(p.guests + 1)} className={step}>+</motion.button>
        </div>
      </div>
      <motion.button whileTap={{ scale: 0.97 }} disabled={p.submitting} onClick={nights ? p.onSubmit : p.onDates} className="mt-4 w-full rounded-2xl bg-primary py-4 font-semibold text-white shadow-[0_12px_30px_rgba(255,90,95,0.4)] disabled:opacity-60">
        {p.submitting ? "Sending…" : nights ? "Request to book" : "Pick your dates"}
      </motion.button>
      <AnimatePresence initial={false}>
        {nights > 0 && (
          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
            <p className="mt-3 text-center text-xs text-neutral-500">You won't be charged yet</p>
            <div className="mt-4 space-y-2.5 text-sm text-neutral-600">
              <div className="flex justify-between"><span>{money(price)} × {nights} night{nights > 1 ? "s" : ""}</span><motion.span key={sub} initial={{ y: -6, opacity: 0 }} animate={{ y: 0, opacity: 1 }}>{money(sub)}</motion.span></div>
              <div className="flex justify-between"><span>Cleaning fee</span><span>{money(n(p.stay.cleaning_fee))}</span></div>
              <div className="flex justify-between border-t border-neutral-200 pt-3 text-base font-bold text-neutral-900"><span>Total</span><motion.span key={total} initial={{ y: -6, opacity: 0 }} animate={{ y: 0, opacity: 1 }}>{money(total)}</motion.span></div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function AskStay({ A, stay }: { A: AppHandle; stay: Row }) {
  const reduce = useReducedMotion();
  const [q, setQ] = useState("");
  const [asked, setAsked] = useState("");
  const [answer, setAnswer] = useState("");
  const [busy, setBusy] = useState(false);
  const [failed, setFailed] = useState(false);
  const ask = async () => {
    const text = q.trim();
    if (!text || busy) return;
    setBusy(true);
    setFailed(false);
    setAnswer("");
    setAsked(text);
    try {
      const facts = "Title: " + s(stay.title) + "\nType: " + s(stay.kind) + "\nPlace: " + s(stay.city) + ", " + s(stay.country) + "\nDescription: " + s(stay.summary) + "\nAmenities: " + s(stay.amenities) + "\nSleeps " + n(stay.max_guests) + ", " + n(stay.bedrooms) + " bedroom(s), " + n(stay.baths) + " bath(s)";
      const out = await A.ai.ask("Listing:\n" + facts + "\n\nGuest question: " + text, { system: "You answer guest questions about one vacation rental using ONLY the listing facts given. If the listing doesn't say, reply that the listing doesn't mention it and suggest asking the host. Friendly, under 60 words.", maxTokens: 220 });
      setAnswer(out.trim());
    } catch (e) {
      setFailed(true);
    }
    setBusy(false);
  };
  return (
    <div className="mt-10 rounded-[28px] border border-neutral-100 bg-neutral-50 p-6">
      <h2 className="flex items-center gap-2 font-serif text-2xl"><Sparkles size={20} className="text-primary" /> Ask about this stay</h2>
      <p className="mb-4 mt-1 text-sm text-neutral-600">Answers come only from this listing's description and amenities.</p>
      <div className="flex gap-2">
        <input aria-label="Ask about this stay" value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") ask(); }} placeholder="e.g. Is it good for kids?" className="min-w-0 flex-1 rounded-2xl border border-neutral-200 bg-white px-4 py-3 text-sm outline-none focus:border-primary" />
        <motion.button whileTap={reduce ? undefined : { scale: 0.95 }} onClick={ask} disabled={busy || !q.trim()} className="shrink-0 rounded-2xl bg-neutral-900 px-5 py-3 text-sm font-semibold text-white disabled:opacity-50">{busy ? "Asking…" : "Ask"}</motion.button>
      </div>
      {busy && <div className="mt-4 h-16 animate-pulse rounded-2xl bg-white" />}
      <AnimatePresence>
        {!busy && failed && (
          <motion.p initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="mt-4 rounded-2xl bg-white p-4 text-sm text-neutral-600">AI is resting right now, try again soon.</motion.p>
        )}
        {!busy && answer && (
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="mt-4 rounded-2xl bg-white p-4 shadow-[0_6px_20px_rgba(16,24,40,0.06)]">
            <p className="text-xs font-semibold uppercase tracking-wider text-neutral-400">{asked}</p>
            <p className="mt-1 leading-relaxed text-neutral-800">{answer}</p>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

function Detail(props: { A: AppHandle; stay: Row; fav: boolean; toggleFav: () => void; onClose: () => void; toast: (m: string, bad?: boolean) => void; desktop: boolean; pics?: Pics }) {
  const { A, stay, desktop } = props;
  const reduce = useReducedMotion();
  const id = s(stay.id);
  const photos = photosOf(stay, props.pics);
  const host = A.rows("host").find((h) => s(h.id) === s(stay.host_id));
  const hostName = host ? s(host.name) : "your host";
  const today = useMemo(() => todayIso(), []);
  const [extra, setExtra] = useState<Range[]>([]);
  const rev = A.revision("booked_range");
  const busy = useMemo(() => A.rows("booked_range").filter((r) => s(r.stay_id) === id && r.active !== false).map((r) => ({ a: s(r.check_in).slice(0, 10), b: s(r.check_out).slice(0, 10) })).concat(extra), [rev, id, extra, A]);
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [guests, setGuests] = useState(Math.min(2, n(stay.max_guests) || 1));
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [sheet, setSheet] = useState(false);
  const [gal, setGal] = useState<number | null>(null);
  const calRef = useRef<HTMLDivElement>(null);
  const guestRows = A.rows("guest");
  const reviews = A.rows("review").filter((r, i, a) => s(r.stay_id) === id && a.findIndex((x) => s(x.booking_id) === s(r.booking_id)) === i);
  const amen = s(stay.amenities).split(",").map((x) => x.trim()).filter(Boolean);

  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape" && gal === null && !sheet) props.onClose(); };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  });

  const pick = (d: string) => {
    if (!start || end) { setStart(d); setEnd(""); return; }
    if (d <= start) { setStart(d); return; }
    if (busy.some((r) => r.a < d && r.b > start)) { setStart(d); props.toast("Those dates overlap a booking", true); return; }
    setEnd(d);
  };
  const scrollToCal = () => { setSheet(false); if (calRef.current) calRef.current.scrollIntoView({ behavior: "smooth", block: "center" }); };

  const submit = async () => {
    setSubmitting(true);
    const nn = diffDays(start, end);
    try {
      await A.create("booking", { stay_id: id, guest_id: A.me("guest"), host_id: s(stay.host_id), check_in: start, check_out: end, guests, nights: nn, total: nn * n(stay.price_per_night) + n(stay.cleaning_fee), status: "requested" });
      setExtra((e) => e.concat([{ a: start, b: end }]));
      setDone(true);
      props.toast("Request sent to " + hostName);
    } catch (e) {
      props.toast(e instanceof Error ? e.message : "Couldn't send request", true);
    }
    setSubmitting(false);
  };

  const panel = <Panel stay={stay} start={start} end={end} guests={guests} setGuests={setGuests} submitting={submitting} done={done} hostName={hostName.split(" ")[0]} onSubmit={submit} onTrips={() => A.navigate("/trips")} onDates={scrollToCal} />;
  const nights = start && end ? diffDays(start, end) : 0;
  const fade = reduce ? {} : { initial: { opacity: 0, y: 24 }, animate: { opacity: 1, y: 0 }, transition: { delay: 0.12, duration: 0.4 } };

  return (
    <div className="fixed inset-0 z-50">
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 bg-white" />
      <div className="absolute inset-0 overflow-y-auto">
        <div className="mx-auto max-w-6xl pb-32 lg:px-8 lg:pb-16">
          <motion.div {...fade} className="hidden items-center justify-between py-5 lg:flex">
            <button onClick={props.onClose} className="flex items-center gap-2 rounded-full border border-neutral-200 px-4 py-2 text-sm font-medium hover:bg-neutral-50"><ArrowLeft size={16} /> Back to stays</button>
            <button onClick={props.toggleFav} className="flex items-center gap-2 rounded-full border border-neutral-200 px-4 py-2 text-sm font-medium hover:bg-neutral-50"><Heart size={16} className={props.fav ? "fill-primary text-primary" : ""} /> Save</button>
          </motion.div>

          {desktop ? (
            <div className="grid h-[440px] grid-cols-[2fr_1fr] gap-2 overflow-hidden rounded-[28px]">
              <motion.div layoutId={"cover-" + id} style={{ borderRadius: 28 }} className="relative cursor-pointer overflow-hidden" onClick={() => setGal(0)}>
                <motion.img layout src={photos[0]} alt={s(stay.title)} className="h-full w-full object-cover" />
              </motion.div>
              <motion.div {...fade} className="grid grid-rows-3 gap-2">
                {photos.slice(1, 4).map((p, k) => (
                  <button key={k} aria-label="Open gallery" onClick={() => setGal(k + 1)} className="overflow-hidden rounded-xl">
                    <img src={p} alt="" className="h-full w-full object-cover transition duration-500 hover:scale-105" />
                  </button>
                ))}
              </motion.div>
            </div>
          ) : (
            <div className="relative">
              <motion.div layoutId={"cover-" + id} style={{ borderRadius: 0 }} className="h-[48vh] overflow-hidden rounded-b-[32px]">
                <Carousel photos={photos} alt={s(stay.title)} onTap={(k) => setGal(k)} />
              </motion.div>
              <div className="absolute inset-x-4 top-4 flex justify-between">
                <button aria-label="Back" onClick={props.onClose} className="flex h-10 w-10 items-center justify-center rounded-full bg-white/90 shadow-lg"><ArrowLeft size={18} /></button>
                <motion.button whileTap={{ scale: 0.8 }} aria-label="Save" onClick={props.toggleFav} className="flex h-10 w-10 items-center justify-center rounded-full bg-white/90 shadow-lg"><Heart size={18} className={props.fav ? "fill-primary text-primary" : ""} /></motion.button>
              </div>
            </div>
          )}

          <motion.div {...fade} className="grid gap-12 px-5 pt-6 lg:grid-cols-[1fr_380px] lg:px-0 lg:pt-10">
            <div className="min-w-0">
              <h1 className="font-serif text-3xl leading-tight lg:text-5xl">{s(stay.title)}</h1>
              <p className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-neutral-600">
                <span className="flex items-center gap-1"><MapPin size={15} /> {s(stay.city)}, {s(stay.country)}</span>
                <span className="flex items-center gap-1"><Star size={15} className="fill-neutral-900" /> <b className="text-neutral-900">{n(stay.rating).toFixed(2)}</b> · {n(stay.review_count)} reviews</span>
              </p>
              <p className="mt-2 text-sm text-neutral-500">{s(stay.kind)} · {n(stay.max_guests)} guests · {n(stay.bedrooms)} bedroom{n(stay.bedrooms) > 1 ? "s" : ""} · {n(stay.baths)} bath{n(stay.baths) > 1 ? "s" : ""}</p>

              <div className="my-8 flex items-center gap-4 rounded-3xl bg-neutral-50 p-4">
                {host ? <img src={cov(props.pics, hostName, s(host.photo))} alt={hostName} className="h-14 w-14 rounded-full object-cover" /> : <span className="flex h-14 w-14 items-center justify-center rounded-full bg-primary/10 font-bold text-primary">{hostName.slice(0, 1)}</span>}
                <div className="min-w-0 flex-1">
                  <p className="font-semibold">Hosted by {hostName}</p>
                  <p className="text-sm text-neutral-500">{host && host.superhost ? "Superhost · " : ""}Since {host ? n(host.hosting_since) : "—"} · {host ? n(host.response_rate) : 0}% response rate</p>
                </div>
              </div>

              <p className="text-lg leading-relaxed text-neutral-700">{s(stay.summary)}</p>

              <h2 className="mb-4 mt-10 font-serif text-2xl">What this place offers</h2>
              <div className="grid grid-cols-2 gap-3">
                {amen.map((a, k) => {
                  const Ic = AMEN[a.toLowerCase()] || Check;
                  return (
                    <motion.div key={a} initial={reduce ? false : { opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 + k * 0.04 }} className="flex items-center gap-3 rounded-2xl border border-neutral-100 px-4 py-3 text-sm text-neutral-700">
                      <Ic size={18} className="text-primary" /> {a}
                    </motion.div>
                  );
                })}
              </div>

              <div ref={calRef} className="mt-10 scroll-mt-24">
                <h2 className="font-serif text-2xl">{nights ? nights + " night" + (nights > 1 ? "s" : "") + " in " + s(stay.city) : "Pick your dates"}</h2>
                <p className="mb-5 mt-1 text-sm text-neutral-500">{start && end ? fmt(start) + " → " + fmt(end) : "Struck days are booked."}</p>
                <div className="rounded-3xl border border-neutral-100 p-4 lg:p-6"><Cal busy={busy} start={start} end={end} onPick={pick} today={today} months={desktop ? 2 : 1} /></div>
              </div>

              <AskStay A={A} stay={stay} />

              <h2 className="mb-4 mt-10 flex items-center gap-2 font-serif text-2xl"><Star size={20} className="fill-neutral-900" /> {n(stay.rating).toFixed(2)} · {n(stay.review_count)} reviews</h2>
              {reviews.length === 0 && <p className="rounded-2xl bg-neutral-50 p-5 text-sm text-neutral-500">No reviews yet.</p>}
              <div className="grid gap-4 md:grid-cols-2">
                {reviews.slice(0, 6).map((r) => {
                  const g = guestRows.find((x) => s(x.id) === s(r.guest_id));
                  return (
                    <div key={s(r.id)} className="rounded-3xl border border-neutral-100 p-5">
                      <p className="flex items-center gap-2 text-sm font-semibold">{g ? s(g.name) : "Guest"}<span className="flex text-primary">{Array.from({ length: n(r.rating) }).map((_, k) => <Star key={k} size={12} className="fill-primary" />)}</span></p>
                      <p className="mt-2 text-sm leading-relaxed text-neutral-600">{s(r.comment)}</p>
                    </div>
                  );
                })}
              </div>
            </div>

            <aside className="hidden lg:block"><div className={"sticky top-6 rounded-[28px] border border-neutral-100 bg-white p-6 " + SHADOW}>{panel}</div></aside>
          </motion.div>
        </div>
      </div>

      {!desktop && (
        <motion.div {...fade} className="fixed inset-x-0 bottom-0 z-[52] flex items-center justify-between border-t border-neutral-100 bg-white/95 px-5 py-3 pb-5 backdrop-blur">
          <div><p className="text-lg font-bold">{money(n(stay.price_per_night))} <span className="text-sm font-normal text-neutral-500">night</span></p><p className="text-xs text-neutral-500">{nights ? fmt(start) + " → " + fmt(end) : "Add dates"}</p></div>
          <motion.button whileTap={{ scale: 0.95 }} onClick={() => setSheet(true)} className="rounded-2xl bg-primary px-7 py-3.5 font-semibold text-white shadow-[0_10px_24px_rgba(255,90,95,0.4)]">Reserve</motion.button>
        </motion.div>
      )}

      <AnimatePresence>
        {sheet && !desktop && (
          <>
            <motion.div key="scrim" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setSheet(false)} className="fixed inset-0 z-[54] bg-black/40" />
            <motion.div key="sheet" initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} transition={{ type: "spring", stiffness: 300, damping: 34 }} className="fixed inset-x-0 bottom-0 z-[55] max-h-[88vh] overflow-y-auto rounded-t-[32px] bg-white px-5 pb-8 pt-3">
              <button aria-label="Close" onClick={() => setSheet(false)} className="mx-auto mb-4 block h-1.5 w-10 rounded-full bg-neutral-300" />
              {panel}
            </motion.div>
          </>
        )}
      </AnimatePresence>
      <AnimatePresence>{gal !== null && <Gallery photos={photos} start={gal} title={s(stay.title)} onClose={() => setGal(null)} />}</AnimatePresence>
    </div>
  );
}

export default function NookExplore({ app, pics, peek }: Props) {
  const A = app as AppHandle;
  const reduce = useReducedMotion();
  const stays = A.rows("stay");
  const loading = A.loading("stay") && stays.length === 0;
  const [q, setQ] = useState("");
  const [city, setCity] = useState("All");
  const [guests, setGuests] = useState(0);
  const prices = stays.map((x) => n(x.price_per_night));
  const hi = prices.length ? Math.max(...prices) : 600;
  const [maxP, setMaxP] = useState(0);
  const cap = maxP || hi;
  const [openId, setOpenId] = useState<string | null>(null);
  const [favs, setFavs] = useState<string[]>([]);
  const [toast, setToast] = useState<{ m: string; bad: boolean } | null>(null);
  const [desktop, setDesktop] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(min-width: 1024px)");
    const f = () => setDesktop(mq.matches);
    f();
    mq.addEventListener("change", f);
    return () => mq.removeEventListener("change", f);
  }, []);
  useEffect(() => {
    if (!toast) return;
    const t = window.setTimeout(() => setToast(null), 3200);
    return () => window.clearTimeout(t);
  }, [toast]);

  useEffect(() => {
    const m = peek ? stays.find((x) => s(x.title) === peek) : undefined;
    if (m) setOpenId(s(m.id));
  }, [stays.length]);
  const cities = useMemo(() => ["All"].concat(Array.from(new Set(stays.map((x) => s(x.city))))), [stays]);
  const list = stays.filter((x) => (city === "All" || s(x.city) === city) && (!guests || n(x.max_guests) >= guests) && n(x.price_per_night) <= cap && (!q || (s(x.title) + s(x.city) + s(x.country)).toLowerCase().includes(q.toLowerCase())));
  const open = stays.find((x) => s(x.id) === openId);
  const toggleFav = (id: string) => setFavs((f) => (f.includes(id) ? f.filter((x) => x !== id) : f.concat([id])));
  const name = A.user.name || "Guest";

  return (
    <LayoutGroup>
      <div className="min-h-screen bg-white text-neutral-900">
        <header className="sticky top-0 z-30 border-b border-neutral-100 bg-white/85 backdrop-blur-xl">
          <div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-3 lg:px-10">
            <div className="flex items-center gap-2">
              <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary text-white"><Home size={18} /></span>
              <span className="text-xl font-bold tracking-tight">nook</span>
            </div>
            <nav className="hidden gap-1 lg:flex">
              <span className="rounded-full bg-neutral-900 px-5 py-2 text-sm font-semibold text-white">Explore</span>
              <button onClick={() => A.navigate("/trips")} className="rounded-full px-5 py-2 text-sm font-semibold text-neutral-600 hover:bg-neutral-100">Trips</button>
            </nav>
            <div className="flex items-center gap-2">
              <span className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10 font-bold text-primary">{name.slice(0, 1).toUpperCase()}</span>
              <button aria-label="Sign out" onClick={() => A.auth.signOut()} className="flex h-10 w-10 items-center justify-center rounded-full text-neutral-500 hover:bg-neutral-100"><LogOut size={18} /></button>
            </div>
          </div>
        </header>

        <main className="mx-auto max-w-7xl px-5 pb-32 pt-8 lg:px-10 lg:pb-16 lg:pt-12">
          <motion.div initial={reduce ? false : { opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
            <p className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">Stays worth the trip</p>
            <h1 className="mt-2 max-w-2xl font-serif text-4xl leading-[1.05] lg:text-6xl">Find your next <span className="text-primary">nook.</span></h1>
          </motion.div>

          <div className={"mt-8 grid gap-3 rounded-[28px] border border-neutral-100 bg-white p-3 lg:grid-cols-[1.4fr_1fr_1.2fr] lg:items-center " + SHADOW}>
            <label className="flex items-center gap-3 rounded-2xl bg-neutral-50 px-4 py-3">
              <Search size={18} className="text-neutral-400" />
              <input aria-label="Search stays" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Where to?" className="w-full bg-transparent text-sm outline-none placeholder:text-neutral-400" />
            </label>
            <div className="flex items-center justify-between rounded-2xl bg-neutral-50 px-4 py-2.5">
              <span className="flex items-center gap-2 text-sm text-neutral-600"><Users size={17} className="text-neutral-400" /> {guests ? guests + " guest" + (guests > 1 ? "s" : "") : "Any guests"}</span>
              <span className="flex gap-2">
                <motion.button whileTap={{ scale: 0.85 }} aria-label="Fewer guests" disabled={guests === 0} onClick={() => setGuests(guests - 1)} className="flex h-8 w-8 items-center justify-center rounded-full border border-neutral-300 bg-white disabled:opacity-30">−</motion.button>
                <motion.button whileTap={{ scale: 0.85 }} aria-label="More guests" onClick={() => setGuests(Math.min(10, guests + 1))} className="flex h-8 w-8 items-center justify-center rounded-full border border-neutral-300 bg-white">+</motion.button>
              </span>
            </div>
            <div className="rounded-2xl bg-neutral-50 px-4 py-2.5">
              <div className="flex justify-between text-sm text-neutral-600"><span>Max per night</span><b className="text-neutral-900">{money(cap)}</b></div>
              <input aria-label="Max price per night" type="range" min={50} max={hi} step={10} value={cap} onChange={(e) => setMaxP(+e.target.value)} className="w-full accent-[#FF5A5F]" />
            </div>
          </div>

