import { useState, useEffect } from "react";
import { motion, AnimatePresence, LayoutGroup, useReducedMotion, animate } from "motion/react";
import { Star, MapPin, Home, Calendar, LogOut, Check, Search, X, Users, Plane } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type Row = Record<string, unknown>;
type Pics = Record<string, string | string[]>;
type Props = { app?: AppHandle; pics?: Pics };
const cov = (p: Pics | undefined, k: string, d: string) => {
  const v = p ? p[k] : undefined;
  return Array.isArray(v) ? v[0] : typeof v === "string" ? v : d;
};

const s = (v: unknown) => (v == null ? "" : String(v));
const n = (v: unknown) => Number(v) || 0;
const money = (v: number) => "$" + Math.round(v).toLocaleString("en-US");
const d10 = (v: unknown) => s(v).slice(0, 10);
const pad = (x: number) => String(x).padStart(2, "0");
const utc = (d: string) => Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10));
const fmt = (d: string) => new Date(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10)).toLocaleDateString("en-US", { month: "short", day: "numeric" });
const SHADOW = "shadow-[0_1px_2px_rgba(16,24,40,0.04),0_8px_28px_rgba(16,24,40,0.07)]";
const TONE: Record<string, string> = { requested: "bg-amber-50 text-amber-700", confirmed: "bg-emerald-50 text-emerald-700", completed: "bg-neutral-100 text-neutral-600", declined: "bg-red-50 text-red-600" };

function Num({ value, money: isMoney }: { value: number; money?: boolean }) {
  const [v, setV] = useState(0);
  useEffect(() => {
    const c = animate(0, value, { duration: 0.9, ease: "easeOut", onUpdate: (x) => setV(x) });
    return () => c.stop();
  }, [value]);
  return <>{isMoney ? money(v) : Math.round(v)}</>;
}

export default function NookTrips({ app, pics }: Props) {
