};

const s = (v: unknown) => (v == null ? "" : String(v));
const n = (v: unknown) => Number(v) || 0;
const money = (v: number) => "$" + Math.round(v).toLocaleString("en-US");
const d10 = (v: unknown) => s(v).slice(0, 10);
const fmt = (d: string) => new Date(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10)).toLocaleDateString("en-US", { month: "short", day: "numeric" });
const SHADOW = "shadow-[0_1px_2px_rgba(16,24,40,0.04),0_8px_28px_rgba(16,24,40,0.07)]";
const KINDS = ["Villa", "Loft", "Cabin", "Cottage", "Treehouse", "Riad", "Flat", "House"];
const TONE: Record<string, string> = { requested: "bg-amber-50 text-amber-700", confirmed: "bg-emerald-50 text-emerald-700", completed: "bg-neutral-100 text-neutral-600", declined: "bg-red-50 text-red-600" };
const FIELD = "w-full rounded-2xl border border-neutral-200 bg-white px-4 py-3 text-sm outline-none focus:border-primary focus:ring-4 focus:ring-primary/15";
