  const pending = bookings.filter((b) => b.status === "requested");
  const earned = bookings.filter((b) => b.status === "confirmed" || b.status === "completed");
  const total = earned.reduce((t, b) => t + n(b.total), 0);
  const pendingSum = pending.reduce((t, b) => t + n(b.total), 0);
  const nights = earned.reduce((t, b) => t + n(b.nights), 0);

  const months: { key: string; label: string; v: number }[] = [];
  for (let k = 5; k >= 0; k--) {
    const d = new Date(2026, 9 - k, 1);
    const key = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0");
    months.push({ key, label: d.toLocaleDateString("en-US", { month: "short" }), v: earned.filter((b) => d10(b.check_in).slice(0, 7) === key).reduce((t, b) => t + n(b.total), 0) });
  }
  const maxM = Math.max(1, ...months.map((m) => m.v));

  const decide = async (b: Row, to: "confirmed" | "declined") => {
    try {
      await A.transition("booking", s(b.id), "status", to);
      setToast({ m: to === "confirmed" ? "Confirmed — guest notified" : "Request declined", bad: false });
    } catch (e) {
      setToast({ m: e instanceof Error ? e.message : "Couldn't update", bad: true });
    }
  };

  const save = async () => {
    if (!draft || !me) return;
    if (!draft.title.trim() || !draft.city.trim()) { setToast({ m: "Add a title and city", bad: true }); return; }
    setBusy(true);
    const vals: Row = { host_id: me, title: draft.title.trim(), city: draft.city.trim(), country: draft.country.trim() || draft.city.trim(), kind: draft.kind, summary: draft.summary.trim() || "A lovely place to stay.", price_per_night: n(draft.price_per_night), cleaning_fee: n(draft.cleaning_fee), max_guests: n(draft.max_guests) || 1, bedrooms: n(draft.bedrooms) || 1, baths: n(draft.baths) || 1, amenities: draft.amenities, cover: draft.cover || DEFAULT_PHOTO };
    try {
      if (draft.id) await A.update("stay", draft.id, vals);
      else await A.create("stay", { ...vals, rating: 5, review_count: 0 });
      setToast({ m: draft.id ? "Listing updated" : "Listing published", bad: false });
      setDraft(null);
    } catch (e) {
      setToast({ m: e instanceof Error ? e.message : "Couldn't save", bad: true });
    }
    setBusy(false);
  };

  const upload = async (f: File | undefined) => {
    if (!f || !draft) return;
    try {
      const r = await A.upload(f);
      setDraft({ ...draft, cover: r.url });
    } catch (e) {
      setToast({ m: "Upload failed", bad: true });
    }
  };

  const edit = (x: Row) => setDraft({ id: s(x.id), title: s(x.title), city: s(x.city), country: s(x.country), kind: s(x.kind), price_per_night: s(x.price_per_night), cleaning_fee: s(x.cleaning_fee), max_guests: s(x.max_guests), bedrooms: s(x.bedrooms), baths: s(x.baths), summary: s(x.summary), amenities: s(x.amenities), cover: cov(pics, s(x.title), s(x.cover)) });
  const tabs: [Tab, string, typeof Home][] = [["listings", "Listings", LayoutGrid], ["requests", "Requests", Inbox], ["earnings", "Earnings", Wallet]];
  const shown = bookings.filter((b) => flt === "all" || b.status === flt).sort((a, b) => d10(a.check_in).localeCompare(d10(b.check_in)));
  const set = (k: keyof Draft, v: string) => setDraft((d) => (d ? { ...d, [k]: v } : d));

  return (
    <LayoutGroup>
      <div className="min-h-screen bg-[#FAFAFA] text-neutral-900 lg:grid lg:grid-cols-[260px_1fr]">
        <aside className="sticky top-0 hidden h-screen flex-col border-r border-neutral-100 bg-white p-6 lg:flex">
          <div className="flex items-center gap-2">
            <span className="flex h-10 w-10 items-center justify-center rounded-2xl bg-primary text-white shadow-[0_8px_24px_rgba(255,90,95,0.45)]"><Home size={20} /></span>
            <span className="text-2xl font-bold tracking-tight">nook</span>
            <span className="ml-1 rounded-full bg-neutral-900 px-2 py-0.5 text-[10px] font-bold uppercase text-white">host</span>
          </div>
          <nav className="mt-10 space-y-1">
            {tabs.map(([k, label, Ic]) => (
              <button key={k} onClick={() => setTab(k)} className={"relative flex w-full items-center gap-3 rounded-2xl px-4 py-3 text-sm font-semibold transition " + (tab === k ? "text-primary" : "text-neutral-500 hover:bg-neutral-50")}>
                {tab === k && <motion.span layoutId="hostNav" className="absolute inset-0 rounded-2xl bg-primary/10" transition={{ type: "spring", stiffness: 420, damping: 34 }} />}
                <Ic size={18} className="relative" /> <span className="relative">{label}</span>
                {k === "requests" && pending.length > 0 && <span className="relative ml-auto rounded-full bg-primary px-2 py-0.5 text-xs text-white">{pending.length}</span>}
              </button>
            ))}
          </nav>
          <div className="mt-auto flex items-center gap-3 rounded-2xl bg-neutral-50 p-3">
            {hostRow ? <img src={cov(pics, name, s(hostRow.photo))} alt={name} className="h-10 w-10 rounded-full object-cover" /> : <span className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10 font-bold text-primary">{name.slice(0, 1)}</span>}
            <div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{name}</p><p className="text-xs text-neutral-500">{hostRow && hostRow.superhost ? "Superhost" : "Host"}</p></div>
            <button aria-label="Sign out" onClick={() => A.auth.signOut()} className="text-neutral-400 hover:text-neutral-700"><LogOut size={18} /></button>
          </div>
        </aside>

        <div className="min-w-0">
          <header className="sticky top-0 z-30 flex items-center justify-between border-b border-neutral-100 bg-white/85 px-5 py-3 backdrop-blur-xl lg:hidden">
            <div className="flex items-center gap-2"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-primary text-white"><Home size={18} /></span><span className="text-xl font-bold">nook</span><span className="rounded-full bg-neutral-900 px-2 py-0.5 text-[10px] font-bold uppercase text-white">host</span></div>
            <button aria-label="Sign out" onClick={() => A.auth.signOut()} className="flex h-10 w-10 items-center justify-center rounded-full text-neutral-500"><LogOut size={18} /></button>
          </header>

          <main className="mx-auto max-w-5xl px-5 pb-32 pt-8 lg:px-10 lg:pb-16 lg:pt-12">
            <AnimatePresence mode="wait" initial={false}>
              <motion.div key={tab} initial={reduce ? false : { opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8 }} transition={{ duration: 0.25 }}>
                {tab === "listings" && (
                  <>
                    <div className="flex items-end justify-between gap-4">
                      <div><p className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">Hello, {name.split(" ")[0]}</p><h1 className="mt-2 font-serif text-4xl lg:text-5xl">Your listings</h1></div>
                      <motion.button whileTap={{ scale: 0.95 }} onClick={() => setDraft({ ...blank })} className="flex items-center gap-2 rounded-full bg-primary px-5 py-3 text-sm font-semibold text-white shadow-[0_10px_24px_rgba(255,90,95,0.4)]"><Plus size={16} /> Add listing</motion.button>
                    </div>
                    {stays.length === 0 ? (
                      <div className="mt-8 flex flex-col items-center rounded-[28px] bg-white px-6 py-16 text-center"><Home size={32} className="mb-3 text-primary" /><h3 className="font-serif text-2xl">No listings yet</h3><p className="mt-1 text-sm text-neutral-500">Publish your first nook and start hosting.</p></div>
                    ) : (
                      <div className="mt-8 grid gap-6 sm:grid-cols-2">
                        {stays.map((x, i) => (
                          <motion.div key={s(x.id)} initial={reduce ? false : { opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.07, type: "spring", stiffness: 150, damping: 20 }} whileTap={{ scale: 0.985 }} className={"overflow-hidden rounded-[28px] bg-white " + SHADOW}>
                            <div className="relative aspect-[16/10]"><img src={cov(pics, s(x.title), s(x.cover))} alt={s(x.title)} className="absolute inset-0 h-full w-full object-cover" /><span className="absolute left-3 top-3 rounded-full bg-white/90 px-3 py-1 text-xs font-semibold">{s(x.kind)}</span></div>
                            <div className="p-5">
                              <div className="flex items-start justify-between gap-3"><h3 className="font-serif text-xl leading-tight">{s(x.title)}</h3><span className="flex items-center gap-1 text-sm"><Star size={14} className="fill-neutral-900" /> {n(x.rating).toFixed(2)}</span></div>
                              <p className="mt-1 flex items-center gap-1 text-sm text-neutral-500"><MapPin size={13} /> {s(x.city)}, {s(x.country)}</p>
                              <div className="mt-4 flex items-center justify-between"><span className="font-bold">{money(n(x.price_per_night))}<span className="text-sm font-normal text-neutral-500"> / night</span></span><button onClick={() => edit(x)} className="flex items-center gap-1.5 rounded-full border border-neutral-200 px-4 py-2 text-sm font-semibold hover:bg-neutral-50"><Pencil size={14} /> Edit</button></div>
                            </div>
                          </motion.div>
                        ))}
                      </div>
                    )}
                  </>
                )}

                {tab === "requests" && (
                  <>
                    <p className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">Bookings</p>
                    <h1 className="mt-2 font-serif text-4xl lg:text-5xl">Requests</h1>
                    <div className="mt-6 flex gap-2 overflow-x-auto">
                      {[["requested", "Pending"], ["confirmed", "Confirmed"], ["completed", "Completed"], ["all", "All"]].map(([k, l]) => (
                        <button key={k} onClick={() => setFlt(k)} className={"relative shrink-0 rounded-full border px-5 py-2 text-sm font-semibold " + (flt === k ? "border-transparent text-white" : "border-neutral-200 bg-white text-neutral-600")}>
                          {flt === k && <motion.span layoutId="reqPill" className="absolute inset-0 rounded-full bg-neutral-900" />}
                          <span className="relative">{l}</span>
                        </button>
                      ))}
                    </div>
                    <div className="mt-6 space-y-4">
                      <AnimatePresence mode="popLayout">
                        {shown.length === 0 && <motion.div key="empty" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="rounded-[28px] bg-white px-6 py-14 text-center"><Inbox size={30} className="mx-auto mb-3 text-primary" /><h3 className="font-serif text-2xl">All caught up</h3><p className="text-sm text-neutral-500">New requests will show up here.</p></motion.div>}
                        {shown.map((b, i) => {
                          const g = guestOf(b);
                          const st = stayOf(b);
                          return (
                            <motion.div key={s(b.id)} layout initial={reduce ? false : { opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, x: 60 }} transition={{ delay: i * 0.05, type: "spring", stiffness: 180, damping: 24 }} className={"flex flex-col gap-4 rounded-[28px] bg-white p-5 sm:flex-row sm:items-center " + SHADOW}>
                              <div className="flex min-w-0 flex-1 items-center gap-4">
                                {g ? <img src={cov(pics, s(g.name), s(g.photo))} alt="" className="h-14 w-14 shrink-0 rounded-full object-cover" /> : <span className="flex h-14 w-14 shrink-0 items-center justify-center rounded-full bg-primary/10 font-bold text-primary">?</span>}
                                <div className="min-w-0">
                                  <p className="flex flex-wrap items-center gap-2 font-semibold">{g ? s(g.name) : "Guest"}<span className={"rounded-full px-2.5 py-0.5 text-[11px] font-bold uppercase " + (TONE[s(b.status)] || "")}>{s(b.status)}</span></p>
                                  <p className="truncate text-sm text-neutral-500">{st ? s(st.title) : ""}</p>
                                  <p className="mt-1 flex flex-wrap items-center gap-x-3 text-sm text-neutral-700"><span className="flex items-center gap-1"><Calendar size={13} /> {fmt(d10(b.check_in))} → {fmt(d10(b.check_out))}</span><span className="flex items-center gap-1"><Users size={13} /> {n(b.guests)}</span><b>{money(n(b.total))}</b></p>
                                  {s(b.note) && <p className="mt-1 text-sm italic text-neutral-500">“{s(b.note)}”</p>}
                                </div>
                              </div>
                              {b.status === "requested" && (
                                <div className="flex gap-2 sm:flex-col">
                                  <motion.button whileTap={{ scale: 0.94 }} onClick={() => decide(b, "confirmed")} className="flex flex-1 items-center justify-center gap-1.5 rounded-full bg-primary px-5 py-2.5 text-sm font-semibold text-white shadow-[0_8px_20px_rgba(255,90,95,0.35)]"><Check size={15} /> Accept</motion.button>
                                  <motion.button whileTap={{ scale: 0.94 }} onClick={() => decide(b, "declined")} className="flex flex-1 items-center justify-center gap-1.5 rounded-full border border-neutral-200 px-5 py-2.5 text-sm font-semibold text-neutral-700"><X size={15} /> Decline</motion.button>
                                </div>
                              )}
                            </motion.div>
                          );
                        })}
                      </AnimatePresence>
                    </div>
                  </>
                )}

                {tab === "earnings" && (
                  <>
                    <p className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">Payouts</p>
                    <h1 className="mt-2 font-serif text-4xl lg:text-5xl">Earnings</h1>
                    <div className="mt-8 grid gap-4 lg:grid-cols-[1.4fr_1fr_1fr]">
                      <div className="rounded-[28px] bg-gradient-to-br from-primary to-[#FF8A7A] p-6 text-white shadow-[0_20px_50px_rgba(255,90,95,0.35)]"><p className="text-sm font-medium text-white/80">Total earned</p><p className="mt-2 text-5xl font-bold tracking-tight"><Num value={total} isMoney /></p><p className="mt-2 text-sm text-white/80">{earned.length} bookings · {nights} nights hosted</p></div>
                      <div className={"rounded-[28px] bg-white p-6 " + SHADOW}><p className="text-sm text-neutral-500">Awaiting your reply</p><p className="mt-2 text-3xl font-bold"><Num value={pendingSum} isMoney /></p><p className="mt-1 text-sm text-neutral-500">{pending.length} pending request{pending.length === 1 ? "" : "s"}</p></div>
                      <div className={"rounded-[28px] bg-white p-6 " + SHADOW}><p className="text-sm text-neutral-500">Listings</p><p className="mt-2 text-3xl font-bold"><Num value={stays.length} /></p><p className="mt-1 text-sm text-neutral-500">live on Nook</p></div>
                    </div>
                    <div className={"mt-4 rounded-[28px] bg-white p-6 " + SHADOW}>
                      <p className="font-semibold">Last six months</p>
                      <div className="mt-6 flex h-48 items-end gap-3">
                        {months.map((m, i) => (
                          <div key={m.key} className="flex h-full flex-1 flex-col items-center justify-end gap-2">
                            <span className="text-xs font-semibold text-neutral-500">{m.v ? money(m.v) : ""}</span>
                            <motion.div initial={reduce ? false : { height: 0 }} animate={{ height: Math.max(6, (m.v / maxM) * 130) }} transition={{ delay: i * 0.08, type: "spring", stiffness: 120, damping: 18 }} className={"w-full rounded-t-2xl " + (m.v ? "bg-primary" : "bg-neutral-100")} />
                            <span className="text-xs text-neutral-400">{m.label}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                    <div className={"mt-4 rounded-[28px] bg-white p-6 " + SHADOW}>
                      <p className="font-semibold">By listing</p>
                      <div className="mt-4 space-y-4">
                        {stays.map((x) => {
                          const v = earned.filter((b) => s(b.stay_id) === s(x.id)).reduce((t, b) => t + n(b.total), 0);
                          return (
                            <div key={s(x.id)}>
                              <div className="mb-1.5 flex justify-between text-sm"><span className="font-medium">{s(x.title)}</span><b>{money(v)}</b></div>
                              <div className="h-2 overflow-hidden rounded-full bg-neutral-100"><motion.div initial={reduce ? false : { width: 0 }} animate={{ width: total ? (v / total) * 100 + "%" : "0%" }} transition={{ duration: 0.9 }} className="h-full rounded-full bg-primary" /></div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  </>
                )}
              </motion.div>
            </AnimatePresence>
          </main>
        </div>

        <nav className="fixed inset-x-0 bottom-0 z-30 flex border-t border-neutral-100 bg-white/90 pb-4 pt-2 backdrop-blur-xl lg:hidden">
          {tabs.map(([k, label, Ic]) => (
            <button key={k} onClick={() => setTab(k)} className={"relative flex flex-1 flex-col items-center gap-0.5 text-xs font-semibold " + (tab === k ? "text-primary" : "text-neutral-400")}>
              <Ic size={22} /> {label}
              {k === "requests" && pending.length > 0 && <span className="absolute right-[28%] top-0 h-4 min-w-4 rounded-full bg-primary px-1 text-[10px] text-white">{pending.length}</span>}
            </button>
          ))}
        </nav>

        <AnimatePresence>
          {draft && (
            <>
              <motion.div key="scrim" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setDraft(null)} className="fixed inset-0 z-40 bg-black/40" />
              <motion.div key="sheet" initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} transition={{ type: "spring", stiffness: 300, damping: 34 }} className="fixed inset-x-0 bottom-0 z-50 mx-auto max-h-[92vh] max-w-xl overflow-y-auto rounded-t-[32px] bg-white px-6 pb-8 pt-5 lg:bottom-6 lg:rounded-[32px]">
                <div className="mb-4 flex items-center justify-between"><h3 className="font-serif text-2xl">{draft.id ? "Edit listing" : "New listing"}</h3><button aria-label="Close" onClick={() => setDraft(null)} className="flex h-9 w-9 items-center justify-center rounded-full bg-neutral-100"><X size={16} /></button></div>
                <div className="space-y-3">
                  <div className="relative flex h-36 items-center justify-center overflow-hidden rounded-2xl bg-neutral-100">
                    {draft.cover && <img src={draft.cover} alt="Cover" className="absolute inset-0 h-full w-full object-cover" />}
                    <label className="relative flex cursor-pointer items-center gap-2 rounded-full bg-white/95 px-4 py-2 text-sm font-semibold shadow"><Upload size={15} /> {draft.cover ? "Change cover" : "Upload cover"}<input aria-label="Cover photo" type="file" accept="image/*" className="hidden" onChange={(e) => upload(e.target.files ? e.target.files[0] : undefined)} /></label>
                  </div>
                  <input aria-label="Title" className={FIELD} placeholder="Title" value={draft.title} onChange={(e) => set("title", e.target.value)} />
                  <div className="grid grid-cols-2 gap-3"><input aria-label="City" className={FIELD} placeholder="City" value={draft.city} onChange={(e) => set("city", e.target.value)} /><input aria-label="Country" className={FIELD} placeholder="Country" value={draft.country} onChange={(e) => set("country", e.target.value)} /></div>
                  <select aria-label="Type" className={FIELD} value={draft.kind} onChange={(e) => set("kind", e.target.value)}>{KINDS.map((k) => <option key={k}>{k}</option>)}</select>
                  <div className="grid grid-cols-2 gap-3">
                    {([["price_per_night", "Price / night"], ["cleaning_fee", "Cleaning fee"], ["max_guests", "Max guests"], ["bedrooms", "Bedrooms"]] as [keyof Draft, string][]).map(([k, l]) => <label key={k} className="text-xs font-semibold text-neutral-500">{l}<input aria-label={l} type="number" min={0} className={FIELD + " mt-1"} value={draft[k]} onChange={(e) => set(k, e.target.value)} /></label>)}
                  </div>
                  <textarea aria-label="Description" rows={3} className={FIELD + " resize-none"} placeholder="Describe the place" value={draft.summary} onChange={(e) => set("summary", e.target.value)} />
                  <input aria-label="Amenities" className={FIELD} placeholder="Amenities, comma separated" value={draft.amenities} onChange={(e) => set("amenities", e.target.value)} />
                  <motion.button whileTap={{ scale: 0.97 }} disabled={busy} onClick={save} className="w-full rounded-2xl bg-primary py-4 font-semibold text-white shadow-[0_12px_30px_rgba(255,90,95,0.4)] disabled:opacity-60">{busy ? "Saving…" : draft.id ? "Save changes" : "Publish listing"}</motion.button>
                </div>
              </motion.div>
            </>
          )}
        </AnimatePresence>

        <AnimatePresence>
          {toast && (
            <motion.div initial={{ opacity: 0, y: 30, scale: 0.9 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 20 }} className="fixed bottom-24 left-1/2 z-[70] -translate-x-1/2 rounded-full bg-neutral-900 px-5 py-3 text-sm font-semibold text-white shadow-2xl lg:bottom-8">
              <span className="flex items-center gap-2">{toast.bad ? <X size={16} className="text-primary" /> : <Check size={16} className="text-emerald-400" />} {toast.m}</span>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </LayoutGroup>
  );
}
